// Real receipts from the owner's 2026-09 upload (the tuning bundle's
// extraction.json): ids, fields and the stored OCR lines verbatim — garbles
// and all (only the card's last four digits are masked to 0000). The
// duplicate tests run the pure dedup helpers over them.

export interface OwnerReceipt {
  id: string;
  fileName: string;
  originalFileName: string;
  vendor: { value: string };
  date: { value: string };
  amount: { value: number };
  flags: { code: "duplicate" | "stale_date"; message: string; severity: "warn" | "info" }[];
  ocrLines: { text: string }[];
}

